/*
 * A171175  Permutation of the natural numbers: 0 together with the partial
 *          sums of A171174.
 * https://oeis.org/A171175
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  easy, nonn
 * Formula:   a(n) is generated by alternating blocks. Block m (m>=1) has
 *            length 2m and contains: indices: C(m)+0, C(m)+1, … ,C(m)+2m-1
 *            where C(m)=m^2 - m + 1 (start index of block m). For k=0..m-1:
 *            a(C(m)+2k) = m^2 + k + 1 // odd‑index positions in OEIS
 *            numbering a(C(m)+2k+1) = m^2 - k // even‑index positions...
 * Range:     u8 n <= 63, u16 n <= 63, u32 n <= 63, u64 n <= 63, u128 n <= 63,
 *            big any n
 * Helpers:   block_of
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdbool.h>
#include "../utils/block_of.h"

seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;

    idx_t m = block_of(n);
    /* start index of block m */
    unsigned __int128 start = (unsigned __int128)m * m - m + 1;
    idx_t offset = n - (idx_t)start;          /* 0 <= offset < 2*m */

    seq_t msq = (seq_t)m * m;                 /* m^2 in seq_t space */

    if ((offset & 1) == 0) {                  /* even offset -> odd OEIS index */
        idx_t k = offset >> 1;
        return msq + (seq_t)k + 1;
    } else {                                  /* odd offset -> even OEIS index */
        idx_t k = offset >> 1;
        return msq - (seq_t)k;
    }
}
